<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/services/TelefoniaVentasLlamadasService.php';
$checks=0;
$check=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$end=['evento'=>'NOTIFY_OUT_END','internal'=>'150','is_recorded'=>1,'call_id_with_rec'=>'150.123456','duration'=>18,'disposition'=>'answered'];
$ready=['evento'=>'NOTIFY_RECORD','internal'=>'','call_id_with_rec'=>'150.123456'];
$a=TelefoniaVentasLlamadasService::evidenciaAudio([$end,$ready],'150');
$check($a['segmentos']===['150.123456'],'El cierre propio aporta la extensión que RECORD no incluye.');
$check($a['audio_motivo']==='referencia_propia','Referencia propia, sin inferirla por número.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$ready],'150')['segmentos']===[],'RECORD global solo no autoriza audio.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$ready],'150')['audio_motivo']==='sin_tramo','Explicar referencia sin tramo.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$end],'150')['segmentos']===['150.123456'],'END grabado propio permite consultar la referencia exacta.');
$end['evento']='NOTIFY_END';$check(TelefoniaVentasLlamadasService::evidenciaAudio([$end,$ready],'150')['segmentos']===['150.123456'],'Entrante transferida con cierre propio.');
$source=$end;$source['internal']='100';
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$source,$ready],'150')['segmentos']===[],'No tomar el cierre de Recepción.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$source,$end,$ready],'150')['audio_motivo']==='compartida','Referencia compartida entre extensiones es ambigua.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$source,$end,$ready],'150')['segmentos']===[],'No reproducir una referencia compartida.');
$legacy=$ready;$legacy['internal']='150';$check(TelefoniaVentasLlamadasService::evidenciaAudio([$legacy],'150')['segmentos']===['150.123456'],'Conservar RECORD con extensión explícita.');
$invalid=$end;$invalid['call_id_with_rec']='https://ajeno.test/audio.mp3';$check(TelefoniaVentasLlamadasService::evidenciaAudio([$invalid],'150')['segmentos']===[],'No aceptar URL como identificador.');
$missing=$end;$missing['call_id_with_rec']='';$check(TelefoniaVentasLlamadasService::evidenciaAudio([$missing],'150')['audio_motivo']==='pendiente_referencia','is_recorded sin ID no inventa un archivo.');
$unflagged=$end;$unflagged['is_recorded']=0;
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$unflagged],'150')['segmentos']===[],'Una referencia contradictoria requiere confirmación.');
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$unflagged,$ready],'150')['segmentos']===['150.123456'],'RECORD confirma el mismo ID atribuido al cierre propio.');
$second=$end;$second['call_id_with_rec']='record-second-150';
$check(TelefoniaVentasLlamadasService::evidenciaAudio([$end,$second,$ready],'150')['segmentos']===['150.123456','record-second-150'],'Múltiples tramos propios, deduplicados.');
$call=['pbx_call_id'=>'pbx-evidencia-01','finalizada'=>true,'conectada'=>true,'segmentos'=>[],'registro'=>null];
$check(TelefoniaVentasLlamadasService::presentacionAudio($call)['estado']==='pendiente_resultado','No confundir resultado pendiente con audio ausente.');
$call['registro']=['resultado'=>'BUZON_VOZ'];$call['segmentos']=['150.123456'];
$check(!TelefoniaVentasLlamadasService::presentacionAudio($call)['disponible'],'Buzón sigue sin reproducción de conversación.');
$call['registro']=['resultado'=>'INTERESADO'];$check(TelefoniaVentasLlamadasService::presentacionAudio($call)['disponible'],'Conversación y referencia propia habilitan la consulta.');
$call['pbx_call_id']='';$check(TelefoniaVentasLlamadasService::presentacionAudio($call)['estado']==='sin_llamada','Intentos sin referencia continúan diferenciados.');
echo "Ventas audio: $checks contratos de evidencia y presentación aprobados.\n";
